sys_ux_client_script.script:
function evaluateProperty({api, helpers}) {
  var startOfWeek = moment().startOf('week');
  var days = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

  var currentHabitId = api.context.repeater_1?.item?.value?.habit?.value;
  var tasks = api.data.this_week_habit_task?.results || [];

  var weekDates = [];

  for (var i = 0; i < 7; i++) {
    var date = moment(startOfWeek).add(i, 'days');
    var dateStr = date.format('YYYY-MM-DD');

    var match = tasks.find(function(task) {
      return task.tracked_habit?.value === currentHabitId && 
             task.due_date?.value?.startsWith(dateStr);
    });

    weekDates.push({
      date: dateStr,
      dayLabel: days[i],
      taskSysId: match?.sys_id?.value || null,
      state: match?.state?.value || null
    });
  }

  return weekDates;
}
